head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = 'ULDBNS10900.xml';
scwin.vMktactCd = '205'; //채권시장조치구분코드
scwin.vIsuCd = '', scwin.hasAttachDoc = '';
scwin.gBndApplId, scwin.gProcsStat = '';
scwin.vBndListProcsTpCd = 1; //채권처리구분(1:신청,2:접수)
scwin.vDtlInfoRowCount = 0;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.processGp; //접수 1, 반송 2, 처리완료 3, 수정 4, 팀장확인 6, 표준코드요청 9			
scwin.vMergeTpCd, scwin.vBndNewIsuCd = '';
scwin.vRegYn = 'N';
scwin.btnStat = new Object();
scwin.vViewYN = 'N';
scwin.vRowPos = 0;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명  	 : fn_list_sync
 * 설명       : 목록조회
 ***********************************************/
scwin.fn_list_sync = function() {
    var dsNm = 'BNS_APPL_ACPT_LIST';
    var qryId = 'lds.stf.bnscommon.select.listApplAndAcpt';
    var param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_MKTACT_CD=' + scwin.vMktactCd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    if (scwin.vBndListProcsTpCd == 1) {
        $c.bns.ShowWinSmall(grd_List1);
    } else {
        $c.bns.ShowWinSmall(grd_List2);
    }
};



/********************************************** 
 * 함수명  	 : fn_dtl_sync
 * 설명       : 상세조회
 ***********************************************/
scwin.fn_dtl_sync = function() {
    var dsNm = 'BNS_CHG_BND_INFO';
    var qryId = 'lds.stf.bnschg.select.readChgBndInfo_205';
    var param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_MKTACT_CD=' + scwin.vMktactCd;
    param += '&{P}V_BND_APPL_ID=' + scwin.gBndApplId;
    param += '&{P}V_VIEW_YN=' + scwin.vViewYN;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_DtlInfo, dsNm, qryId, param);
};


/********************************************** 
 * 설명 : 채권신고담당자 조회
 ***********************************************/
scwin.fn_Search2 = function() {
    dts_List3.removeAll();
    var isur_cd = dts_List.getCellData(dts_List.getRowPosition(), "ISUR_CD");
    var dsNm = 'BNS_BND_DECL_CHRG_LIST';
    var qryId = 'lds.stf.bnsdecl_mgr.select.selectBndDeclChrgList';
    var param = '&{P}V_ISUR_CD=' + isur_cd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List3, dsNm, qryId, param);
};


/********************************************** 
 * 함수명  	 : fn_ChgTab_Act
 * 설명       : 버튼 활성/비활성, 필드 ReadOnly 속성 제거/부여
 ***********************************************/
scwin.fn_ChgTab_Act = function(vBndListProcsTpCd) {
    if (scwin.vBndListProcsTpCd == 1) {
        btn_ReqStdCd.src = "../img/bns/btn_33_d.gif";
        btn_Dtl_Div.src = "../img/bns/btn_23_d.gif";
        edt_ExerAmt.setReadOnly("true");
    } else if (scwin.vBndListProcsTpCd == 2) {
        btn_ReqStdCd.src = "../img/bns/btn_33.gif";
        btn_Dtl_Div.src = "../img/bns/btn_23.gif";
        edt_ExerAmt.setReadOnly("false");
    }
};



/********************************************** 
 * 함수명   : fn_InputCheck
 * 설명      : 필수 입력 값을 체크한다. 
 ***********************************************/
scwin.fn_InputCheck = function() {
    if ($c.stf.getObjectValue(edt_StrtDd) == '') {
        $c.win.alert("[적용일]을 입력하십시오.");
        edt_StrtDd.focus();
        return false;
    }
    if ($c.bns.fn_CheckDateObj(edt_StrtDd, "적용일")) {
        return false;
    }
    if ($c.stf.getObjectValue(txb_UnqIsuNm) == '') {
        $c.win.alert("[한글종목고유명]을 입력하십시오.");
        txb_UnqIsuNm.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_UnqIsuEngNm) == '') {
        $c.win.alert("[영문종목고유명]을 입력하십시오.");
        txb_UnqIsuEngNm.focus();
        return false;
    }
    //자리수 체크
    if (!$c.stf.checkMaxLength(txb_BasIsuNm, 60, '한글기준명')) return false;
    if (!$c.stf.checkMaxLength(txb_BasIsuAbbrv, 40, '한글기준약명')) return false;
    if (!$c.stf.checkMaxLength(txb_UnqIsuNm, 20, '한글고유명')) return false;
    if (!$c.stf.checkMaxLength(txb_BasIsuEngNm, 60, '영문기준명')) return false;
    if (!$c.stf.checkMaxLength(txb_BasIsuEngAbbrv, 40, '영문기준약명')) return false;
    if (!$c.stf.checkMaxLength(txb_UnqIsuEngNm, 20, '영문고유명')) return false;
    var pattern = /^[ㄱ-ㅎ|ㅏ-ㅣ|가-힣]/;
    var str = $c.stf.getObjectValue(txb_BasIsuEngNm);
    for (var i = 0; i < str.length; i++) {
        if (pattern.test(str.substring(i, i + 1))) {
            $c.win.alert('영문기준명에 한글은 사용할 수 없습니다');
            txb_BasIsuEngNm.focus();
            return false;
        }
    }
    var str = $c.stf.getObjectValue(txb_BasIsuEngAbbrv);
    for (var i = 0; i < str.length; i++) {
        if (pattern.test(str.substring(i, i + 1))) {
            $c.win.alert('영문기준약명에 한글은 사용할 수 없습니다');
            txb_BasIsuEngAbbrv.focus();
            return false;
        }
    }
    var str = $c.stf.getObjectValue(txb_UnqIsuEngNm);
    for (var i = 0; i < str.length; i++) {
        if (pattern.test(str.substring(i, i + 1))) {
            $c.win.alert('영문고유명에 한글은 사용할 수 없습니다');
            txb_UnqIsuEngNm.focus();
            return false;
        }
    }
    return true;
};


/********************************************** 
 * 함수명   : fn_AcptProcsCheck
 * 설명      : 접수, 처리완료시 공통 체크 구문
 ***********************************************/
scwin.fn_AcptProcsCheck = function() {
    //필수입력값 체크
    if (scwin.fn_InputCheck() == false) return 1;

    //적용일,매매일,마감일,채권마감 체크		
    if ($c.bns.fn_CheckCmData(scwin.vScrenID, dts_CheckCmData, $c.stf.getObjectValue(edt_StrtDd), scwin.gBndApplId) > 0) return 1;
    scwin.vIsuCd = dts_DtlInfo.getCellData(1, "ISU_CD");
    scwin.hasAttachDoc = dts_DtlInfo.getCellData(1, "HAS_ATTACH_DOC");

    //변경된 데이터가 없더라도 데이터셋 전송
    dts_DtlInfo.UseChangeInfo = "False";
    return 0;
};


/********************************************** 
 * 함수명   : fn_Acpt
 * 설명       : 신청데이터를 접수 처리한다.
 ***********************************************/
scwin.fn_Acpt = function() {
    //접수, 처리완료 공통 체크
    if (scwin.fn_AcptProcsCheck() > 0) return;

    //복수조치 체크
    if ($c.bns.fn_CheckMultActImpsblRule(scwin.vScrenID, dts_Temp, scwin.vIsuCd, scwin.vMktactCd, $c.stf.getObjectValue(edt_StrtDd)) > 0) return;

    //첨부문서 체크	
    if (!$c.bns.fn_EndConfirm(scwin.hasAttachDoc, '접수')) return;

    //변경상장수수료 및 연부과금 등록
    scwin.fn_GetPar = fn_GetChgBndListFee;
    scwin.fn_SetPar = fn_SetChgBndListFee;
    $c.bns.fn_PopChgListFee(grd_List1);
    if (scwin.vRegYn == "N") return;
    var url = "/bns/ChgList.do?method=ApplAcpt";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    url += "&MKTACT_TP_CD=" + scwin.vMktactCd;
    url += "&REG_YN=" + scwin.vRegYn;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo, I:pInput3=dts_ChgListFee)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_ProcsComplt
 * 설명       : 처리완료 및 수정을 처리한다.
 ***********************************************/
scwin.fn_ProcsComplt = function() {
    //접수, 처리완료 공통 체크
    if (scwin.fn_AcptProcsCheck() > 0) return;

    //복수조치 체크
    if ($c.bns.fn_CheckMultActImpsblRuleProcEnd(scwin.vScrenID, dts_Temp, scwin.vIsuCd, scwin.vMktactCd, $c.stf.getObjectValue(edt_StrtDd)) > 0) return;
    var url;
    if (scwin.processGp == '4') {
        //접수 후 수정 및 반송시 체크한다.			
        if ($c.bns.fn_CheckModAndRet(scwin.vScrenID, dts_CheckCmData, scwin.gBndApplId) > 0) return;
        if (!confirm("수정처리 하시겠습니까?")) return;
        url = "/bns/ChgList.do?method=updateAcpt";
    } else {
        if (scwin.vBndNewIsuCd == '') {
            $c.win.alert('분리된 일반사채의 종목코드가 없습니다.');
            return;
        }
        if (!$c.bns.fn_EndConfirm(scwin.hasAttachDoc, '처리완료')) return;

        //신규상장수수료 및 연부과금 등록
        scwin.fn_GetPar = fn_GetNewBndListFee;
        scwin.fn_SetPar = fn_SetNewBndListFee;
        $c.bns.fn_PopNewListFee(grd_List1);
        if (scwin.vRegYn == "N") return;
        url = "/bns/ChgList.do?method=processAcptProcessComplt";
    }
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    url += "&MKTACT_TP_CD=" + scwin.vMktactCd;
    url += "&BND_NEW_ISU_CD=" + scwin.vBndNewIsuCd;
    url += "&REG_YN=" + scwin.vRegYn;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo, I:pInput3=dts_NewListFee)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_GetCommonKey
 * 설명       : 팝업에 넘길 키데이터를 정의한다.
 ***********************************************/
scwin.fn_GetCommonKey = function(arrPar) {
    arrPar[0] = {
        //첨부문서 목록 팝업	
        BND_APPL_ID: dts_DtlInfo.getCellData(1, "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: dts_DtlInfo.getCellData(1, "BND_LIST_PROCS_TP_CD"),
        ISU_CD: dts_DtlInfo.getCellData(1, "ISU_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetReturn
 * 설명       : 반송 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetReturn = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: dts_DtlInfo.getCellData(1, "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: dts_DtlInfo.getCellData(1, "BND_LIST_PROCS_TP_CD"),
        ISUR_NM: dts_DtlInfo.getCellData(1, "BFCHG_ISUR_NM"),
        ISU_NM: dts_DtlInfo.getCellData(1, "BW_APPL_ISU_NM")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetReturn
 * 설명       : 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetReturn = function(arrPar) {
    if ("Y" == arrPar[0].SUCCESS_YN) {
        scwin.fn_list_sync();
    }
};



/********************************************** 
 * 함수명   : fn_GetParIsuDelInfo
 * 설명       : 종목상세 목록 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsuDelInfo = function(arrPar) {
    arrPar[0] = {
        STD_CD: dts_DtlInfo.getCellData(1, "ISU_CD"),
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetParApprovFileWrt
 * 설명       : 결재파일생성 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParApprovFileWrt = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: scwin.gBndApplId,
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd,
        BND_MKTACT_TP_CD: scwin.vMktactCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetBasNm
 * 설명       : 채권기준명 팝업에 넘길 키데이터를 정의한다.
 ***********************************************/
scwin.fn_GetBasNm = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: dts_DtlInfo.getCellData(1, "ISUR_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetBasNm
 * 설명       : 채권기준명 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetBasNm = function(arrPar) {
    $c.stf.setObjectValue(txb_BasIsuNm, arrPar[0].BAS_ISU_NM);
    $c.stf.setObjectValue(txb_BasIsuAbbrv, arrPar[0].BAS_ISU_ABBRV);
    $c.stf.setObjectValue(txb_BasIsuEngNm, arrPar[0].BAS_ISU_ENG_NM);
    $c.stf.setObjectValue(txb_BasIsuEngAbbrv, arrPar[0].BAS_ISU_ENG_ABBRV);
};


/********************************************** 
 * 함수명   : fn_GetParDivIsuDelInfo
 * 설명       : 분리종목상세 목록 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParDivIsuDelInfo = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: dts_DtlInfo.getCellData(1, "BND_APPL_ID")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_PopDetailDiv
 * 설명       : 분리종목 상세정보 팝업을 보여준다.
 ***********************************************/
scwin.fn_PopDetailDiv = async function(grdObj) {
    $c.bns.fn_SetPopupPos(grdObj, 'E');
    await $c.frame.CreateDialogFrame("ULDBNS10901", "/bnschg/ULDBNS10901.gfm", "분리종목 상세정보 조회", obj_left, obj_top, 1260, 660, "window");
};


/********************************************** 
 * 함수명   : fn_SetSaveHeader
 * 설명       : 팝업 데이터를 넘겨받을 데이터셋 헤더 설정
 ***********************************************/
scwin.fn_SetSaveHeader = function() {
    dts_ChgListFee.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BNS_CHG_ANULFEE_INSERT_INFO";
    dts_ChgListFee.Reset();
    dts_NewListFee.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BNS_ANULFEE_DTL";
    dts_NewListFee.Reset();
};

/********************************************** 
 * 함수명   : fn_GetChgBndListFee
 * 설명       : 변경상장 수수료 등록 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetChgBndListFee = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: dts_DtlInfo.getCellData(1, "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd,
        MKTACT_TP_CD: scwin.vMktactCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetChgBndListFee
 * 설명       : 변경상장 수수료 등록 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetChgBndListFee = function(arrPar) {
    scwin.vRegYn = arrPar[0].REG_YN;
};


/********************************************** 
 * 함수명   : fn_GetNewBndListFee
 * 설명       : 신규상장 수수료 등록 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetNewBndListFee = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: dts_DtlInfo.getCellData(1, "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd,
        MKTACT_TP_CD: scwin.vMktactCd,
        LIST_DD: '',
        ISU_NM: '',
        BND_CLSS_CD: dts_DtlInfo.getCellData(1, "AFCHG_BND_CLASS_CD"),
        BND_TP_CD: dts_DtlInfo.getCellData(1, "AFCHG_BND_TP_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetNewBndListFee
 * 설명       : 신규상장 수수료 등록 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetNewBndListFee = function(arrPar) {
    if (arrPar[0].REG_YN == 'Y') {
        scwin.vRegYn = arrPar[0].REG_YN;
    }
};



/********************************************** 
 * 함수명   : fn_ProcBtnStat
 * 설명       : 처리 상태가 처리완료일 경우, 처리완료 버튼 비활성화
 ***********************************************/
scwin.fn_ProcBtnStat = function() {
    if (scwin.gProcsStat == "처리완료") {
        btn_Proc.src = "../img/bns/btn_20_d.gif";
        scwin.btnStat.Proc = "dis";
    } else {
        btn_Proc.src = "../img/bns/btn_20.gif";
        scwin.btnStat.Proc = "en";
    }
};
scwin.gform_onload = function() {
    $c.bns.BnsPanelToGroupBox(pnl_Req); //패널라운드처리(신청)
    $c.bns.BnsPanelToGroupBox(pnl_DtlInfo); //패널라운드처리(상세)
    $c.bns.BnsPanelToGroupBox(pnl_Acpt); //패널라운드처리(접수)

    tab_List.setSelectedTabIndex(1);
    scwin.fn_list_sync(); //목록 조회

    //팀장확인데이터셋설정	

    //dts_Temp.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_Temp.insertRow();
    scwin.fn_ChgTab_Act(scwin.vBndListProcsTpCd);

    //변경상장 수수료 등록, 신규상장 수수료 등록 데이터셋설정
    scwin.fn_SetSaveHeader();
};
scwin.tab_List_OnSelChanged = function(nIndex) {
    scwin.vBndListProcsTpCd = nIndex;
    if (scwin.vBndListProcsTpCd == 2) {
        txb_Dtl.setValue("비분리형BW최초행사 접수내역");
    } else {
        txb_Dtl.setValue("비분리형BW최초행사 신청내역");
    }
    scwin.fn_list_sync(); //목록 조회
    scwin.fn_ChgTab_Act(scwin.vBndListProcsTpCd);
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (scwin.vBndListProcsTpCd == 2) {
        $c.bns.CloseWinSmall(rowcount, grd_List2);
        //접수,수정,처리완료,팀장확인 시 해당 ROW로 이동
        $c.bns.fn_RowPos(dts_List, scwin.vRowPos);
    } else {
        $c.bns.CloseWinSmall(rowcount, grd_List1);
    }
};
scwin.dts_List_OnRowPosChanged = function(row) {
    if (row > 0) {
        scwin.gBndApplId = dts_List.getCellData(row, "BND_APPL_ID");
        if (scwin.vBndListProcsTpCd == 2) {
            scwin.vMergeTpCd = dts_List.getCellData(row, "MERGE_TP_CD");
        }
        scwin.fn_dtl_sync();
        scwin.gProcsStat = dts_List.getCellData(row, "PROCS_STAT");
        scwin.fn_ProcBtnStat();

        // 채권신고담당자 조회
        scwin.fn_Search2();
    } else {
        dts_List3.removeAll();
        dts_DtlInfo.removeAll();
        scwin.vDtlInfoRowCount = 0;
    }
};
scwin.dts_DtlInfo_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_DtlInfo_OnLoadCompleted = function(rowcount) {
    scwin.vDtlInfoRowCount = rowcount;
    scwin.vBndNewIsuCd = dts_DtlInfo.getCellData(dts_DtlInfo.getRowPosition(), "BND_NEW_ISU_CD");
    if (scwin.vBndNewIsuCd != '') {
        btn_ReqStdCd.src = "../img/bns/btn_33_d.gif";
        scwin.btnStat.ReqStdCd = "dis";
    } else {
        btn_ReqStdCd.src = "../img/bns/btn_33.gif";
        scwin.btnStat.ReqStdCd = "en";
    }
    edt_StkRelCorpbndExerPrc.RightMargin = 5;
    edt_ExerAmt.RightMargin = 5;
    edt_BfhgIsuAmt.RightMargin = 5;
    edt_AfhgIsuAmt.RightMargin = 5;
    edt_BfchgListAmt.RightMargin = 5;
    edt_AfchgListAmt.RightMargin = 5;
    edt_NewIsuAmt.RightMargin = 5;
    edt_NewListAmt.RightMargin = 5;
};
scwin.img_StrtDd_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    popUpCalendar2(edt_StrtDd);
};
scwin.img_BasIsuNm_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    if (dts_DtlInfo.getCellData(1, "BFCHG_ISUR_NM") == '') return;
    scwin.fn_GetPar = fn_GetBasNm;
    scwin.fn_SetPar = fn_SetBasNm;
    $c.bns.fn_PopBndBasNmSearch(grd_List1);
};
scwin.btn_Acpt_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    scwin.processGp = '1';
    scwin.fn_Acpt();
};
scwin.btn_Ret_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    scwin.processGp = '2';
    scwin.fn_GetPar = fn_GetReturn;
    scwin.fn_SetPar = fn_SetReturn;
    $c.bns.fn_PopReturn(grd_List1);
};
scwin.btn_Ret2_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    if ($c.bns.fn_CheckModAndRet(scwin.vScrenID, dts_CheckCmData, scwin.gBndApplId) > 0) return;
    scwin.processGp = '2';
    scwin.fn_GetPar = fn_GetReturn;
    scwin.fn_SetPar = fn_SetReturn;
    $c.bns.fn_PopReturn(grd_List1);
};
scwin.btn_Attach_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    if ("N" == dts_DtlInfo.getCellData(1, "HAS_ATTACH_DOC")) {
        $c.win.alert("연결된 팩스/첨부문서가 없습니다.");
        return;
    }
    scwin.fn_GetPar = fn_GetCommonKey;
    $c.bns.fn_PopAttachDocSearch(grd_List1);
};
scwin.btn_Dtl_Bfchg_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    scwin.fn_GetPar = fn_GetParIsuDelInfo;
    $c.bns.fn_PopIsuDetail(grd_List1);
};
scwin.btn_ApprovFileCreat_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    scwin.fn_GetPar = fn_GetParApprovFileWrt;
    $c.bns.fn_PopApprovFileWrt(grd_List1);
};
scwin.btn_Proc_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    if (scwin.btnStat.Proc == "dis") return;
    scwin.vRowPos = dts_List.getRowPosition();
    scwin.processGp = '3';
    scwin.fn_ProcsComplt();

};
scwin.btn_Mod_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    scwin.vRowPos = dts_List.getRowPosition();
    scwin.processGp = '4';
    scwin.fn_ProcsComplt();
};
scwin.btn_TeamleadrConfrm_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    scwin.vRowPos = dts_List.getRowPosition();
    scwin.processGp = "6";
    var confrmDd = dts_List.getCellData(dts_List.getRowPosition(), "TEAMLEADER_CONFRM_DD");
    $c.bns.fn_TeamleadrConfrm1(scwin.vScrenID, trs_Save, confrmDd, scwin.gBndApplId, scwin.vBndListProcsTpCd);
};
scwin.btn_Dtl_Div_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    if (scwin.vBndListProcsTpCd != 2) return;
    if (dts_DtlInfo.getCellData(dts_DtlInfo.getRowPosition(), "BND_NEW_ISU_CD") != '') {
        scwin.fn_GetPar = fn_GetParDivIsuDelInfo;
        scwin.fn_PopDetailDiv(grd_List1);
    } else {
        $c.win.alert("종목이 생성되지 않았습니다.");
    }
};
scwin.btn_ReqStdCd_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    if (scwin.vBndListProcsTpCd != 2) return;
    if (scwin.fn_InputCheck() == false) return;
    if (scwin.btnStat.ReqStdCd == 'dis') return;
    scwin.processGp = 9;
    $c.bns.fn_ChgIsu_ProcessStdCdReq(scwin.vScrenID, dts_CheckCmData, trs_Save, scwin.gBndApplId, dts_DtlInfo, scwin.vMktactCd, dts_ReqStdCd);
};
scwin.trs_Save_OnFail = function() {
    if (scwin.processGp == '1') {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "접수"));
    }
    if (scwin.processGp == '3') {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "처리완료"));
    }
    if (scwin.processGp == '4') {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "수정"));
    }
    if (scwin.processGp == '6') {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "팀장확인"));
    }
    if (scwin.processGp == '9') {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "표준코드요청"));
    }
};
scwin.trs_Save_OnSuccess = function() {
    if (scwin.processGp == '1') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "접수"));
        scwin.fn_list_sync();
    }
    if (scwin.processGp == '3') {
        $c.win.alert($c.stf.getMessageParam("MSG-0001"));
        scwin.fn_list_sync();
    }
    if (scwin.processGp == '4') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
        scwin.fn_list_sync();
    }
    if (scwin.processGp == '6') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "팀장확인"));
        scwin.fn_list_sync();
    }
    if (scwin.processGp == '9') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "표준코드요청"));
        dts_DtlInfo.Reset();
    }
    scwin.vRegYn = 'N';
};
